export function prepareFiniteWindows(input,tokenCounter,{maxTokens=256}={}){
  if(!Number.isSafeInteger(maxTokens)||maxTokens<8||maxTokens>256||typeof tokenCounter?.tokenCount!=='function'||!/^[a-f0-9]{64}$/u.test(tokenCounter.policy_sha256??''))fail('Verified pinned tokenizer and bounded token capacity required');
  const text=input.normalizedText.slice(input.start,input.end),words=[...text.matchAll(/\S+/gu)],wordCuts=[0,...words.slice(1).map(m=>m.index),text.length],pointCuts=[0];for(const c of text)pointCuts.push(pointCuts.at(-1)+c.length);
  const measured=(a,b)=>{let window;try{window=input.encodeWindow({start:input.start+a,end:input.start+b,includeEndZeroWidth:b===text.length});}catch(error){if(error.code==='NATIVE_DECORATION_PROJECTION_BOUND')return {tokens:Infinity};throw error;}const tokens=tokenCounter.tokenCount(window.text);if(!Number.isSafeInteger(tokens)||tokens<1)fail('Pinned tokenizer returned invalid count');return {...window,tokens};};
  const plan=(cuts,mode)=>{const windows=[];let i=0;while(i<cuts.length-1){let lo=i+1,hi=cuts.length-1,best=-1;while(lo<=hi){const mid=(lo+hi)>>>1;if(measured(cuts[i],cuts[mid]).tokens<=maxTokens){best=mid;lo=mid+1;}else hi=mid-1;}if(best<0)return null;const w=measured(cuts[i],cuts[best]);if(w.tokens>maxTokens)fail('Measured finite window exceeds token capacity');windows.push({...w,segmentation:mode,tokenizer_policy_sha256:tokenCounter.policy_sha256});if(windows.length>policy.maximum_windows)fail('Retained window count bound exceeded');i=best;}return windows;};
  const normal=words.length?plan(wordCuts,'COMPLETE_SOURCE_WORDS'):null,windows=normal??plan(pointCuts,'ALL_LANGUAGE_CODEPOINT_FALLBACK');
  if(!windows)throw Object.assign(new Error('A literal source codepoint plus complete encoding exceeds tokenizer capacity; retained failure'),{code:'QA_MINIMUM_CODEPOINT_ENCODING_OVERFLOW'});
  let cursor=input.start;for(const w of windows){if(w.source_range.start!==cursor)fail('Window source coverage gap');cursor=w.source_range.end;}if(cursor!==input.end)fail('Window source coverage incomplete');
  const owned=windows.flatMap(w=>w.zero_events),expected=input.features.zero_events;if(digest(owned)!==digest(expected))fail('Zero-output ownership lost or repeated');
  return {schema:'qa-finite-native-feature-windows-v1',policy_sha256:digest(policy),input_sha256:digest(input.binding),tokenizer_policy_sha256:tokenCounter.policy_sha256,source_range:input.binding.source_range,windows,status:'INFORMATION_REDUCED_TOKENIZER_ONLY_NOT_INFERENCE',fallback_used:!normal,zero_event_coverage_sha256:digest(owned),inference:false,adopted:false};
}

  function encodeWindow({start:low=start,end:high=end,includeEndZeroWidth=false}={}){
    range(normalizedText,low,high);if(low<start||high>end||includeEndZeroWidth&&high!==end)fail('Window exceeds exact selected source span or terminal ownership');
    const cuts=new Set([low,high]);for(const s of spans)if(s.end>low&&s.start<high){cuts.add(Math.max(low,s.start));cuts.add(Math.min(high,s.end));}for(const p of zero.keys())if(p>=low&&p<=high)cuts.add(p);
